pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(address logBefore, address logAfter) internal {
        vm.assume(logBefore != logAfter);
        try c.SetLogFile(logBefore) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetLogFile(logAfter) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(address logBefore, address logAfter) public {
